-- ТЕСТОВЫЕ ДАННЫЕ профиля testdata (шаг 12 Ф3): история заказов для проверки listOrders и ограничения по владельцу (U1).
-- Покупатель A (…a1) и покупатель B (…a2) это условные пользователи: сервис видит только заказы своего sub.
-- Заказы создаются в статусе «создан» и доводятся до нужного статуса теми же переходами, что в работе: триггер контроля статусов включён.
-- Комиссия считается по правилу conventions 4.6 (half-up в копейках), сумма равна цене-снимку на количество (INV-12, INV-13).

insert into orders.orders (id, buyer_id, seller_id, product_id, product_title, quantity, unit_price, amount, commission_rate_bp, commission,
                           delivery_address, created_at) values
  -- A: выдан, два ключа
  ('0199e0a0-0000-7000-8000-000000000301', '0199e0a0-0000-4000-8000-0000000000a1', '0199e0a0-0000-7000-8000-000000000101',
   '0199e0a0-0000-7000-8000-000000000201', 'Лунная тропа: ключ Steam', 2, 149900, 299800, 1000, div(299800::numeric * 1000 + 5000, 10000),
   'buyer@mail.example', '2026-10-03 12:00:00.123+00'),
  -- A: ожидает оплаты
  ('0199e0a0-0000-7000-8000-000000000302', '0199e0a0-0000-4000-8000-0000000000a1', '0199e0a0-0000-7000-8000-000000000102',
   '0199e0a0-0000-7000-8000-000000000203', 'Офисный пакет 2026: лицензия', 1, 399900, 399900, 1000, div(399900::numeric * 1000 + 5000, 10000),
   'buyer@mail.example', '2026-10-03 13:00:00.000+00'),
  -- A: отменён, платёж отклонён
  ('0199e0a0-0000-7000-8000-000000000303', '0199e0a0-0000-4000-8000-0000000000a1', '0199e0a0-0000-7000-8000-000000000101',
   '0199e0a0-0000-7000-8000-000000000202', 'Каменный город: ключ Steam', 1, 99900, 99900, 1000, div(99900::numeric * 1000 + 5000, 10000),
   'buyer@mail.example', '2026-10-02 09:00:00.000+00'),
  -- B: оплачен, чужой заказ: покупателю A он недоступен
  ('0199e0a0-0000-7000-8000-000000000304', '0199e0a0-0000-4000-8000-0000000000a2', '0199e0a0-0000-7000-8000-000000000101',
   '0199e0a0-0000-7000-8000-000000000201', 'Лунная тропа: ключ Steam', 1, 149900, 149900, 1000, div(149900::numeric * 1000 + 5000, 10000),
   'other@mail.example', '2026-10-03 12:30:00.000+00');

-- 301: создан -> ждёт оплаты -> оплачен -> выдан
update orders.orders set status = 'awaiting_payment', reserve_until = '2026-10-03 12:15:00.123+00', session_until = '2026-10-03 12:10:00.123+00',
       payment_session_url = 'https://pay.stub.example/session/301' where id = '0199e0a0-0000-7000-8000-000000000301';
update orders.orders set status = 'paid', paid_at = '2026-10-03 12:05:00.123+00' where id = '0199e0a0-0000-7000-8000-000000000301';
update orders.orders set status = 'issued', issued_at = '2026-10-03 12:06:00.123+00' where id = '0199e0a0-0000-7000-8000-000000000301';

-- 302: создан -> ждёт оплаты (срок резерва далеко в будущем, чтобы в тестах не истёк)
update orders.orders set status = 'awaiting_payment', reserve_until = '2099-01-01 00:15:00+00', session_until = '2099-01-01 00:10:00+00',
       payment_session_url = 'https://pay.stub.example/session/302' where id = '0199e0a0-0000-7000-8000-000000000302';

-- 303: создан -> отменён
update orders.orders set status = 'cancelled', cancel_reason = 'payment_declined' where id = '0199e0a0-0000-7000-8000-000000000303';

-- 304: создан -> ждёт оплаты -> оплачен
update orders.orders set status = 'awaiting_payment', reserve_until = '2026-10-03 12:45:00+00', session_until = '2026-10-03 12:40:00+00',
       payment_session_url = 'https://pay.stub.example/session/304' where id = '0199e0a0-0000-7000-8000-000000000304';
update orders.orders set status = 'paid', paid_at = '2026-10-03 12:35:00+00' where id = '0199e0a0-0000-7000-8000-000000000304';
